from pathlib import Path
import json,hashlib,os,subprocess
import bb_ru46_review as api
api.SYSTEM='You are the authorized complete source-aligned reviewer of Russian editorial paratext and historical image captions for Anton Chekhov, Three Sisters. This is original Russian literature, not a translation. Review every editorial draft against the supplied source facts and image provenance. Improve Russian clarity and fidelity automatically, without changing authenticated title, author, ISBN, source URLs or rights facts. No invented image dating, performers, creators or licenses. Notes are Wikisource editorial, not Chekhov authorial. Return JSON only.'
R=api.ROOT;O=R/'results/ru46-paratext';O.mkdir(parents=True,exist_ok=True);sources=json.loads((R/'inputs/ru46-paratext-input.json').read_text());api.save(O/'input.json',sources);current=api.validate([{'source_id':s['id'],'target':s['draft_target']} for s in sources],sources);turns=[]
for phase in range(8):
 task='Review EVERY editorial Russian draft against its supplied source facts. Check factual fidelity, natural Russian and complete preservation of mandatory source, credit, license and change disclosures. Automatically correct actual defects. Preserve exact URLs, ISBN and fixed metadata. Return JSON only with every row in order in rows(source_id,target) and review(source_id,verdict PASS or CORRECTED,reason).'
 if phase:task+=' Separately compare EVERY CURRENT final_rows target against original source and every prior correction. If already faithful, retain exact current bytes and verdict PASS. CORRECTED means you actually changed current bytes.'
 payload={'task':task,'phase':'INDEPENDENT_SOURCE_COMPARISON' if phase else 'COMPLETE_SOURCE_ALIGNED_CAPTION_AND_METADATA_REVIEW','source_rows':sources,'final_rows':current,'prior_corrections':[c for t in turns for c in t['corrections']]};result,meta=api.checked_call(api.SYSTEM,payload,O/f'phase{phase:02}',sources,True);changes=[{'source_id':a['source_id'],'before':a['target'],'after':b['target']} for a,b in zip(current,result['rows']) if a['target']!=b['target']];turns.append({'phase':phase,'api':meta,'review':result['review'],'corrections':changes});current=result['rows'];api.save(O/'pending.json',{'rows':current,'turns':turns});print('CAPTION_PHASE',phase,'CORRECTIONS',len(changes),flush=True)
 if phase>=1 and not changes and all(r['verdict']=='PASS' for r in result['review']):break
else:raise RuntimeError('CAPTION_SOURCE_COMPARISON_NOT_STABLE')
assert [r['target'] for r in current[-3:]]==[s['draft_target'] for s in sources[-3:]],'FIXED_BIBLIOGRAPHIC_METADATA_CHANGED'
api.save(O/'captions.verified.json',{'state':'ACTUAL_COMPLETE_RANK46_EDITORIAL_PARATEXT_CAPTIONS_AND_METADATA_REVIEWED_AND_SOURCE_COMPARED','run_id':os.environ.get('GITHUB_RUN_ID'),'input_sha256':hashlib.sha256((O/'input.json').read_bytes()).hexdigest(),'rows':current,'turns':turns,'book_release':False})
subprocess.run(['git','add','results/ru46-paratext'],cwd=R,check=True);subprocess.run(['git','commit','-m','Preserve actual complete rank46 editorial paratext and caption review with independent comparison'],cwd=R,check=True);subprocess.run(['git','push','origin','HEAD'],cwd=R,check=True);print('ALL_EDITORIAL_ROWS_SOURCE_COMPARED',flush=True)
